// Logos de plataformas embutidos como base64 — Hostinger não serve public/.
const LOGOS: Record<string, { mime: string; data: string }> = {
  'eduzz.png': { mime: 'image/png', data: '' },
  'hotmart.jpg': { mime: 'image/jpeg', data: '' },
  'instagram.jpg': { mime: 'image/jpeg', data: '' },
  'kiwify.jpg': { mime: 'image/jpeg', data: '' },
  'meta.jpg': { mime: 'image/jpeg', data: '' },
  'monetizze.jpg': { mime: 'image/jpeg', data: '' },
  'whatsapp.jpg': { mime: 'image/jpeg', data: '' },
}

export const dynamic = 'force-dynamic'

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ name: string }> }
) {
  const { name } = await params
  const entry = LOGOS[name]
  if (!entry) return new Response(null, { status: 404 })
  const buf = Buffer.from(entry.data, 'base64')
  return new Response(buf, {
    headers: {
      'Content-Type': entry.mime,
      'Cache-Control': 'public, max-age=31536000, immutable',
      'Content-Length': String(buf.length),
    },
  })
}
